import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Fused custom CUDA kernel to apply channel-wise Softmax followed by Sigmoid
fused_softmax_sigmoid_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <float.h>

__global__ void softmax_sigmoid_fused_kernel(
    const float* __restrict__ x,
    float* __restrict__ out,
    int batch, int channels, int depth, int height, int width
){
    int idx = blockDim.x * blockIdx.x + threadIdx.x;
    int total = batch * depth * height * width;
    if (idx >= total) return;

    // Decompose idx into (b, d, h, w)
    int tmp = idx;
    int w   = tmp % width;   tmp /= width;
    int h   = tmp % height;  tmp /= height;
    int d   = tmp % depth;   tmp /= depth;
    int b   = tmp;

    // Compute starting offset for this (b,d,h,w)
    // Each channel entry is offset by (c * depth * height * width)
    int base = ((b * channels * depth) + d) * height * width + h * width + w;

    // Find the maximum value (for numerical stability)
    float max_val = -FLT_MAX;
    for(int c = 0; c < channels; c++){
        float val = x[base + c * depth * height * width];
        max_val = (val > max_val) ? val : max_val;
    }

    // Compute the sum of exponentials
    float sum_exp = 0.0f;
    for(int c = 0; c < channels; c++){
        float val = x[base + c * depth * height * width];
        sum_exp += __expf(val - max_val);
    }

    // Compute softmax + sigmoid
    for(int c = 0; c < channels; c++){
        float val = x[base + c * depth * height * width];
        val = __expf(val - max_val) / sum_exp;       // Softmax
        val = 1.0f / (1.0f + __expf(-val));          // Sigmoid
        out[base + c * depth * height * width] = val;
    }
}

torch::Tensor fused_softmax_sigmoid_forward(torch::Tensor x) {
    // Assume x is float32, 5D [N, C, D, H, W] and on CUDA
    auto sizes = x.sizes();
    int batch    = sizes[0];
    int channels = sizes[1];
    int depth    = sizes[2];
    int height   = sizes[3];
    int width    = sizes[4];

    auto out = torch::zeros_like(x);

    int total = batch * depth * height * width;
    const int block_size = 256;
    const int grid_size  = (total + block_size - 1) / block_size;

    softmax_sigmoid_fused_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        batch, channels, depth, height, width
    );

    return out;
}
"""

fused_softmax_sigmoid_cpp = r"""
torch::Tensor fused_softmax_sigmoid_forward(torch::Tensor x);
"""

# Build the extension
fused_softmax_sigmoid = load_inline(
    name="fused_softmax_sigmoid",
    cpp_sources=fused_softmax_sigmoid_cpp,
    cuda_sources=fused_softmax_sigmoid_source,
    functions=["fused_softmax_sigmoid_forward"],
    verbose=False,
)

class ModelNew(nn.Module):
    """
    Optimized Model that performs a 3D transposed convolution,
    then applies Softmax+Sigmoid in a single fused custom CUDA kernel.
    """
    def __init__(self, in_channels, out_channels, kernel_size, stride, padding, output_padding, bias=True):
        super(ModelNew, self).__init__()
        self.conv_transpose = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding,
            output_padding=output_padding, bias=bias
        )

    def forward(self, x):
        x = self.conv_transpose(x)
        x = fused_softmax_sigmoid.fused_softmax_sigmoid_forward(x)
        return x
